// ==========================================
// VALIDATE INPUTS FROM AI AGENT
// ==========================================

const input = $input.first().json;

const sessionId = input.session_id || '';
const productName = input.product_name || '';
const productPrice = input.product_price || null;
const productUrl = input.product_url || '';
const productId = input.product_id || null;
const productSku = input.product_sku || '';
const quantity = parseInt(input.quantity) || 1;
const customerComment = input.customer_comment || '';
const shippingMethod = input.shipping_method || '';
const paymentMethod = input.payment_method || '';
const rawName = (input.customer_name || '').trim();
const rawPhone = (input.phone_number || '').trim();

if (!sessionId) {
  return { error: 'session_id is required', success: false };
}

if (!productName) {
  return { error: 'product_name is required', success: false };
}

if (!rawPhone) {
  return { 
    success: false, 
    error: 'phone_number is required',
    response_to_ai: 'Номер телефону обовʼязковий для створення замовлення. Спочатку запитай у клієнта номер телефону.' 
  };
}

// --- Format phone (if provided) ---
let phoneNumber = null;
if (rawPhone) {
  phoneNumber = rawPhone.replace(/[\s\-\(\)]/g, '');

  if (phoneNumber.startsWith('0') && phoneNumber.length === 10) {
    phoneNumber = '+38' + phoneNumber;
  } else if (phoneNumber.startsWith('380') && !phoneNumber.startsWith('+')) {
    phoneNumber = '+' + phoneNumber;
  } else if (phoneNumber.startsWith('+380')) {
    // already correct
  } else {
    phoneNumber = '+38' + phoneNumber; // best effort
  }
}

// --- Format name (if provided) ---
let customerName = '';
if (rawName && rawName.length >= 2) {
  customerName = rawName.split(' ')
    .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

return {
  sessionId,
  customerName,
  phoneNumber,
  productName,
  productPrice,
  productUrl,
  productId,
  productSku,
  quantity,
  customerComment,
  shippingMethod,
  paymentMethod,
};

// ==========================================
// PREPARE SALESDRIVE PAYLOAD
// Uses proper SalesDrive schema with products[] array
// Comment = conversation summary for manager context
// ==========================================

const inputs = $('Validate Inputs').first().json;
const leadRows = $input.first().json;

// leadRows is an array from Supabase REST
const lead = Array.isArray(leadRows) ? leadRows[0] : leadRows;

// Use DB phone first, fallback to AI input
const resolvedPhone = lead?.phone || inputs.phoneNumber;

if (!resolvedPhone) {
  return {
    success: false,
    error: 'No phone found for session: ' + inputs.sessionId,
    response_to_ai: 'Телефон клієнта відсутній. Спочатку потрібно отримати номер телефону.'
  };
}

// Format phone
let phone = (resolvedPhone).replace(/[\s\-\(\)]/g, '');
if (phone.startsWith('0')) phone = '+38' + phone;
else if (phone.startsWith('38') && !phone.startsWith('+')) phone = '+' + phone;
else if (!phone.startsWith('+')) phone = '+38' + phone;

// Parse name parts (fName, lName)
const resolvedName = lead?.name || inputs.customerName || '';
const nameParts = resolvedName.trim().split(/\s+/);
const fName = nameParts[0] || 'Не вказано';
const lName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';

// Build products array
const product = {
  name: inputs.productName,
  costPerItem: inputs.productPrice ? Number(inputs.productPrice) : 0,
  amount: inputs.quantity || 1,
};
if (inputs.productId) product.id = String(inputs.productId);
if (inputs.productSku) product.sku = inputs.productSku;

// Build comment — conversation summary for manager
let comment = '[Chatbot] ';
if (inputs.customerComment) {
  comment += inputs.customerComment;
} else {
  comment += 'Клієнт оформив замовлення через чат-бот на сайті.';
}
if (inputs.productUrl) {
  comment += ' | Посилання: ' + inputs.productUrl;
}

// Map shipping method
const shippingMap = {
  'нова пошта': 'novaposhta',
  'новапошта': 'novaposhta',
  'nova poshta': 'novaposhta',
  'укрпошта': 'ukrposhta',
  'ukrposhta': 'ukrposhta',
  'meest': 'meest',
  'міст': 'meest',
  'самовивіз': 'pickup',
  'pickup': 'pickup',
};
const normalizedShipping = (inputs.shippingMethod || '').toLowerCase().trim();
const shippingMethod = shippingMap[normalizedShipping] || inputs.shippingMethod || '';

return {
  salesdrive: {
    fName: fName,
    lName: lName,
    phone: phone,
    email: lead.email || '',
    products: [product],
    comment: comment,
    shippingMethod: shippingMethod,
    paymentMethod: inputs.paymentMethod || '',
  },
  leadId: lead.id,
  sessionId: inputs.sessionId,
  existingSalesdriveId: lead.salesdrive_id || null,
  productName: inputs.productName,
  productPrice: inputs.productPrice,
  productUrl: inputs.productUrl,
};

// ==========================================
// EXTRACT RESULT & UPDATE SUPABASE
// ==========================================
const prepared = $('Prepare SalesDrive Payload').first().json;
let sdResult = null;
try {
  sdResult = $('SalesDrive: Create New Order').first().json;
} catch (e) {
  sdResult = null;
}

const fName = prepared.salesdrive?.fName || 'Не вказано';
const nameForResponse = fName !== 'Не вказано' ? ` ${fName}` : '';

let salesdriveId = null;
let syncStatus = 'failed';
let responseToAi = '';

if (sdResult && sdResult.success && sdResult.data?.orderId) {
  salesdriveId = String(sdResult.data.orderId);
  syncStatus = 'synced';
  responseToAi = `Замовлення створено! Номер: ${salesdriveId}. Менеджер зателефонує${nameForResponse} найближчим часом.`;
} else if (sdResult && sdResult.orderId) {
  salesdriveId = String(sdResult.orderId);
  syncStatus = 'synced';
  responseToAi = `Замовлення створено! Номер: ${salesdriveId}. Менеджер зателефонує${nameForResponse} найближчим часом.`;
} else {
  syncStatus = 'pending';
  responseToAi = `Заявку на ${prepared.productName} прийнято! Менеджер зателефонує${nameForResponse} найближчим часом.`;
}

return {
  salesdriveId,
  syncStatus,
  sessionId: prepared.sessionId,
  leadId: prepared.leadId,
  response_to_ai: responseToAi,
  success: true,
};
